    "suggestions": [
      "Replace `textwrap.dedent` with explicit string formatting to ensure consistent indentation and avoid version-specific quirks. Example: `'\"\\nimport pytest\\n\\nasync def test_async_behavior(): assert True\\n\\ndef test_sync(): assert True\\n\"'`.",
